import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — select_mul was latently unsound (broadcast along the selected axis)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/select-mul-broadcast.md","filePath":"vendored/graphopt/project/retros/select-mul-broadcast.md"}`),a={name:`graphopt/project/retros/select-mul-broadcast.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-select-mul-was-latently-unsound-broadcast-along-the-selected-axis" tabindex="-1">Retro — <code>select_mul</code> was latently unsound (broadcast along the selected axis) <a class="header-anchor" href="#retro-—-select-mul-was-latently-unsound-broadcast-along-the-selected-axis" aria-label="Permalink to “Retro — select_mul was latently unsound (broadcast along the selected axis)”">​</a></h1><h2 id="what-happened" tabindex="-1">What happened <a class="header-anchor" href="#what-happened" aria-label="Permalink to “What happened”">​</a></h2><p>The view/index oracle (<code>tools/law_view_oracle.py</code>, built to resolve the intake-r2 &quot;unproven&quot; bucket) ran a real-match sweep + satisfiable- instance synthesis on every view-family candidate. Its proposal mirror of <code>select_mul</code> — <code>census:mul_select</code> — came back <strong>conditional</strong>, and the counterexample is real:</p><pre><code>u = (4,), v = (2,4), D = 0
mul(sel(u,0,0), sel(v,0,0)) = u[0] · v[0]   # scalar × vector → [0,0,0,0]
sel(mul(u,v), 0,0)          = (u · v)[0]   # u broadcasts → u · v[0]
                                           #          = [0,1,4,9]
</code></pre><p>Broadcasting <code>mul(u, v)</code> along the <em>selected</em> axis changes the result. The structural precondition the law&#39;s comment described (&quot;shared dim/index metavars enforce it, no check needed&quot;) was true as far as it went — it missed that <code>mul</code>&#39;s broadcast is the other degree of freedom.</p><h2 id="why-it-never-bit" tabindex="-1">Why it never bit <a class="header-anchor" href="#why-it-never-bit" aria-label="Permalink to “Why it never bit”">​</a></h2><p>All 13 real corpus sites had <code>shape(u)[D] == shape(v)[D]</code> — the sites that motivated the law (same-shape projections) satisfy the missing condition by construction. The shipped <code>sink.verify</code> oracles only ever saw the true region. Exactly the matmul-unsoundness pattern: a law true on every real site, false on adversarial bindings, invisible until an adversarial oracle runs.</p><h2 id="fix" tabindex="-1">Fix <a class="header-anchor" href="#fix" aria-label="Permalink to “Fix”">​</a></h2><p>New cond predicate <code>(&quot;dim-eq-attr&quot;, A, K, B, K2)</code> — dims named by attr metavars (<code>shape(u)[D] == shape(v)[D]</code>); <code>select_mul</code> now carries <code>cond=(&quot;dim-eq-attr&quot;, &quot;u&quot;, &quot;D&quot;, &quot;v&quot;, &quot;D&quot;)</code>. Broadcast along <em>other</em> axes stays allowed (u=(2,1), v=(2,4), D=0 still fires — both sides broadcast identically post-selection). The law stays fully serializable — the guard is data. Test: <code>tests/test_select_laws.py::test_select_mul_broadcast_axis_guard</code>.</p><h2 id="second-catch-in-the-same-sweep" tabindex="-1">Second catch in the same sweep <a class="header-anchor" href="#second-catch-in-the-same-sweep" aria-label="Permalink to “Second catch in the same sweep”">​</a></h2><p><code>pow</code>&#39;s shape rule returned the base shape unconditionally — <code>pow((), (4,))</code> reported <code>()</code> while aten evaluates <code>(4,)</code>. Fixed in <code>80b133f</code> (broadcast like the other elementwise binaries). The conditional-candidate sweep surfaced it because the ALiBiAttention <code>mul_unsqueeze_reshape_wl</code> site was accepted on an IR-believed shape execution contradicts.</p><h2 id="the-meta-lesson-twice-now" tabindex="-1">The meta-lesson (twice now) <a class="header-anchor" href="#the-meta-lesson-twice-now" aria-label="Permalink to “The meta-lesson (twice now)”">​</a></h2><p>&quot;Shipped + verified on all real sites&quot; is not &quot;sound&quot;. Both the matmul rank bug and this broadcast bug were caught the same way — an oracle that <em>synthesizes bindings outside the observed corpus</em> (the adversarial witness generator, the view oracle&#39;s shape bank). The adversarial layer is the part of the referee that keeps earning its keep; every shipped law that lacks a <code>cond</code> should eventually get a synthesis pass over its metavar bindings.</p><h2 id="honest-limits" tabindex="-1">Honest limits <a class="header-anchor" href="#honest-limits" aria-label="Permalink to “Honest limits”">​</a></h2><ul><li><code>dim-eq-attr</code> declines when either side&#39;s shape is unknown — the law now won&#39;t fire on shape-less binds (conservative, never wrong).</li><li><code>select_add</code>/<code>select_sub</code>/<code>slice_mul</code>/<code>sub_unsqueeze</code> proposals have the same latent issue as <em>candidates</em> — none are shipped laws yet, and the conditionals their proposals resolved to are the guard table in <code>project/retros/cond-dsl-view-guards.md</code>.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};